// 架空データのみ。実際の依頼書の文字・顧客情報はリポジトリに置かない。
// 構造(見出しと行の並び)だけを、pdf.jsで文字が埋め込まれたPDFから取り出した形に合わせてある。
// 作業内容は「■」のついた項目で表され、所在地の値は見出し行の1行上に来る。
const embedded = (work, extra = {}) => [
    'MFD→JRO   業務依頼書',
    '依頼日   2026/10/20',
    `型式   ${extra.model ?? 'XX-00ZZ0'} 台数   ${extra.units ?? 1}   台`,
    'ポンプ有無   ■有り   □無し   営業担当者 架空太郎',
    '初回設置日   2020/01/10   最終訪問日   2025/1/10',
    '部材出荷予定日   2026/10/21   最終作業履歴 架空の履歴',
    '住居形態   □一戸建て   □マンション   □団地・アパート   □ギャラリー   ■店舗（事務所)',
    `${work[0]}`,
    '依頼業務内容  ',
    `${work[1]}`,
    '代金回収   □有 (   )   ■無   MTS/レンタル   ■有   □無   □レンタル',
    '顧客名 架空商事(株) テスト店   様',
    '〒100-0001   東京都架空区試験1-2-3',
    '所在地  ',
    '電話：   000-0000-0000 携帯：',
    '特記事項',
    '※架空の注意書き',
    '（MS事業本部）   受付年月日 2026/10/20',
    '受付者名 架空花子',
    '依頼SS名 架空SS',
    '備考欄 ご依頼日から7日以内にご対応下さい。'
].join('\n');
const work = {
    filterIrregular: ['□設置工事   □取外し工事   □クレーム □定期ﾌｨﾙﾀｰ交換', '■不定期ﾌｨﾙﾀｰ交換 □移設（取付)   □修理   □現地調査'],
    install: ['■設置工事   □取外し工事   □クレーム □定期ﾌｨﾙﾀｰ交換', '□不定期ﾌｨﾙﾀｰ交換 □移設（取付)   □修理   □現地調査'],
    repair: ['□設置工事   □取外し工事   □クレーム □定期ﾌｨﾙﾀｰ交換', '□不定期ﾌｨﾙﾀｰ交換 □移設（取付)   ■修理   □現地調査'],
    none: ['□設置工事   □取外し工事   □クレーム □定期ﾌｨﾙﾀｰ交換', '□不定期ﾌｨﾙﾀｰ交換 □移設（取付)   □修理   □現地調査']
};
// 画像のみのPDFをOCRした形: 漢字の間に空白が入り、チェック記号(■□)は読み取られず、所在地の値が同じ行に来る。
const ocr = [
    '依頼日 2026/10/20',
    '型 式 XX-00ZZ0 台 数 1 台',
    '依 頼 業 務 内 容',
    '顧 客 名 架空商事(株) テスト店 様',
    '所 在 地 〒100-0001 東京都架空区試験1-2-3',
    '電 話 : 000-0000-0000 携 帯 :',
    '受付年月日 2026/10/20',
    '依頼SS名 架空SS'
].join('\n');
// 依頼書ではない参考資料(精算書・納品書・調査票・コスト試算)。架空データ。
// 実際に起きた誤取り込み(参考資料のページごとに空に近い依頼が作られる)を再現するため、会社名や住所に似た行を含む。
const reference = {
    settlement: n => ['精算書', '請求日   2026/10/20', `ページ ${n}`, '会社名 架空商事(株)', '住所 東京都架空区試験1-2-3', '部品代   0,000円   工賃   0,000円', '合計   0,000円'].join('\n'),
    delivery: n => ['納品書', '納品日   2026/10/21', `No. ${n}`, '架空商事(株) 御中', '品名 フィルター   数量 2', '備考 ご確認ください'].join('\n'),
    survey: n => ['現地調査票', `調査日   2026/10/19   ${n}枚目`, '顧客名 架空商事(株) テスト店   様', '所在地 東京都架空区試験1-2-3', '電話：   000-0000-0000', '設置場所の写真   □有   ■無'].join('\n'),
    cost: n => ['コスト試算', `試算日   2026/10/18   (${n})`, '機種 XX-00ZZ0   台数 1', '部材費   0,000円   作業費   0,000円', '合計   0,000円'].join('\n')
};
// 9ファイル・計29ページ(実際に誤って29件が作られた件数と同じ構成)。
const referenceFiles = [
    ['精算書_架空商事.pdf', 'settlement', 7], ['精算書_架空物産.pdf', 'settlement', 3],
    ['納品書_01.pdf', 'delivery', 4], ['納品書_02.pdf', 'delivery', 2],
    ['調査票_架空店.pdf', 'survey', 3], ['調査票_架空2.pdf', 'survey', 2],
    ['コスト試算_A.pdf', 'cost', 4], ['コスト試算_B.pdf', 'cost', 2], ['精算書_架空3.pdf', 'settlement', 2]
];
module.exports = {embedded, ocr, work, reference, referenceFiles};
